#!/usr/bin/env python3
# GitHub: https://github.com/brunoosz | LinkedIn: https://www.linkedin.com/in/brunocamperlingo/
# fase 2
import os, sys, re, base64, shutil, subprocess, datetime

BASE = sys.argv[1] if len(sys.argv) > 1 else "/root/site_esteira"
SERVER = os.path.join(BASE, "server.js")
VIEWS = os.path.join(BASE, "views")
ARQUIVOS = {'separador_engine.js': '', 'separador.html': '', 'sistema.html': '', 'bloco_a.js': '', 'bloco_b.js': ''}

def dado(nome): return base64.b64decode(ARQUIVOS[nome]).decode("utf-8")

for caminho in (SERVER, os.path.join(VIEWS, "base.html")):
    if not os.path.exists(caminho):
        print("❌ Nao achei " + caminho + ". Rode primeiro o instalar_flowpack.py.")
        sys.exit(1)

carimbo = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
for caminho in (SERVER, os.path.join(VIEWS, "base.html")):
    shutil.copy2(caminho, caminho + ".bak_" + carimbo)
print("Copias de seguranca criadas (.bak_" + carimbo + ")\n")

res = []

def escrever(destino, conteudo, rotulo):
    if os.path.exists(destino) and open(destino, encoding="utf-8").read() == conteudo:
        res.append("⏭️  %s: ja estava atualizado." % rotulo); return
    if os.path.exists(destino): shutil.copy2(destino, destino + ".bak_" + carimbo)
    open(destino, "w", encoding="utf-8").write(conteudo)
    res.append("✅ %s: gravado." % rotulo)

escrever(os.path.join(BASE, "separador_engine.js"), dado("separador_engine.js"), "Motor de visao local (separador_engine.js)")
escrever(os.path.join(VIEWS, "separador.html"), dado("separador.html"), "Pagina Separador")
escrever(os.path.join(VIEWS, "sistema.html"), dado("sistema.html"), "Pagina Status do Sistema")

c = open(SERVER, encoding="utf-8").read()

def aplicar(nome, marcador, funcao):
    global c
    if marcador in c:
        res.append("⏭️  %s: ja estava aplicado." % nome); return
    try:
        novo = funcao(c)
    except Exception as e:
        res.append("❌ %s: %s" % (nome, e)); return
    if novo == c:
        res.append("❌ %s: trecho nao encontrado, me avisa." % nome); return
    c = novo
    res.append("✅ %s: aplicado." % nome)

def unico(texto, trecho):
    if texto.count(trecho) != 1: raise Exception("trecho nao encontrado (%d vezes)" % texto.count(trecho))

def f_bloco_a(t):
    ancora = "\ncicloPollingVisao();\n"
    unico(t, ancora)
    return t.replace(ancora, "\n" + dado("bloco_a.js") + ancora, 1)

def f_polling(t):
    a1 = "const url = `http://${configVisao.ip}:${configVisao.porta || 80}${configVisao.caminho}`;"
    unico(t, a1)
    t = t.replace(a1, a1 + "\n    const inicioQuadro = Date.now();", 1)
    velho = """        const produtoCandidato = await detectarCandidatoLocal(bufferImagem);

        io.emit('visao_frame', {
            imagem: bufferImagem.toString('base64'),
            contagemHoje: obterContagemHojeVisao()
        });

        if (produtoCandidato) {
            recortarZonaDeInteresse(bufferImagem)
                .then(bufferRecortado => processarCandidatoDeProduto(bufferRecortado))
                .catch(() => processarCandidatoDeProduto(bufferImagem));
        }

        setTimeout(cicloPollingVisao, configVisao.intervaloMs || 400);"""
    unico(t, velho)
    novo = """        if (separadorMotor.getConfig().motorLocal) {
            // motor local do Separador: conta, reconhece e aciona o servo sem depender de internet
            io.emit('visao_frame', {
                imagem: bufferImagem.toString('base64'),
                contagemHoje: obterContagemHojeVisao()
            });
            await separadorTratarFrame(bufferImagem);
        } else {
            const produtoCandidato = await detectarCandidatoLocal(bufferImagem);

            io.emit('visao_frame', {
                imagem: bufferImagem.toString('base64'),
                contagemHoje: obterContagemHojeVisao()
            });

            if (produtoCandidato) {
                recortarZonaDeInteresse(bufferImagem)
                    .then(bufferRecortado => processarCandidatoDeProduto(bufferRecortado))
                    .catch(() => processarCandidatoDeProduto(bufferImagem));
            }
        }

        setTimeout(cicloPollingVisao, separadorProximoAtraso(inicioQuadro));"""
    return t.replace(velho, novo, 1)

def f_bloco_b(t):
    ancora = "app.get('/dispenser', loginObrigatorio, (req, res) => res.render('dispenser.html'));"
    unico(t, ancora)
    return t.replace(ancora, ancora + "\n" + dado("bloco_b.js"), 1)

def f_mqtt_conectar(t):
    a = "mqttClient.subscribe([MQTT_TOPIC_DISP_STATUS, MQTT_TOPIC_DISP_ESTADO, MQTT_TOPIC_DISP_CONCLUIDO]);"
    unico(t, a)
    return t.replace(a, a + "\n    mqttClient.subscribe(['separador/status', 'separador/estado']);\n    setTimeout(separadorPublicarConfig, 600);", 1)

def f_mqtt_mensagem(t):
    a = "mqttClient.on('message', (topic, message) => {\n    const valor = message.toString();"
    unico(t, a)
    return t.replace(a, a + "\n    if (topic.startsWith('separador/')) separadorTratarMqtt(topic, valor);", 1)

def f_emergencia(t):
    padrao = re.compile(r"mqttClient\.publish\(MQTT_TOPIC_DISP_EMERGENCIA, (['\"])1\1\);")
    if len(padrao.findall(t)) == 0: raise Exception("nao achei a emergencia do Dispenser")
    return padrao.sub(lambda m: m.group(0) + " mqttClient.publish('separador/emergencia', '1');", t)

def f_socket(t):
    a = "io.on('connection', (socket) => {"
    unico(t, a)
    return t.replace(a, a + "\n    socket.emit('separador_servo', { online: separadorOnline, estado: separadorEstado });", 1)

aplicar("Servidor: motor e funcoes do Separador", "SEPARADOR (fase 2) - visao local", f_bloco_a)
aplicar("Servidor: camera usa o motor local (e pede o proximo quadro mais rapido)", "separadorTratarFrame(bufferImagem)", f_polling)
aplicar("Servidor: paginas e API (Separador e Status do Sistema)", "SEPARADOR (fase 2) - paginas e API", f_bloco_b)
aplicar("Servidor: MQTT (inscricao e configuracao do servo)", "mqttClient.subscribe(['separador/status'", f_mqtt_conectar)
aplicar("Servidor: MQTT (mensagens do servo)", "separadorTratarMqtt(topic, valor);", f_mqtt_mensagem)
aplicar("Servidor: emergencia tambem leva o servo ao centro", "separador/emergencia", f_emergencia)
aplicar("Servidor: estado do servo ao abrir a pagina", "socket.emit('separador_servo'", f_socket)
open(SERVER, "w", encoding="utf-8").write(c)

# menu
caminho_base = os.path.join(VIEWS, "base.html")
b = open(caminho_base, encoding="utf-8").read()

LINK_SEP = """
                <a href="/separador" data-spa-link class="flex items-center gap-3 px-4 py-3.5 sm:py-3 rounded-lg text-sm font-medium transition hover:bg-gray-50 active:bg-gray-100 text-gray-600" id="link-separador">
                    <svg class="w-5 h-5 shrink-0" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h6l4-6h6M10 12l4 6h6"/></svg>
                    Separador
                </a>"""
LINK_SIS = """
                {% if isAdmin %}
                <a href="/sistema" data-spa-link class="flex items-center gap-3 px-4 py-3.5 sm:py-3 rounded-lg text-sm font-medium transition hover:bg-gray-50 active:bg-gray-100 text-gray-600" id="link-sistema">
                    <svg class="w-5 h-5 shrink-0" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12h4l3-8 4 16 3-8h4"/></svg>
                    Status do Sistema
                </a>
                {% endif %}"""

if 'id="link-separador"' in b:
    res.append("⏭️  Menu: item Separador ja existia.")
else:
    m = re.search(r'<a href="/dispenser"[\s\S]*?</a>', b)
    if m:
        b = b[:m.end()] + LINK_SEP + b[m.end():]; res.append("✅ Menu: item Separador adicionado (abaixo de Dispenser).")
    else: res.append("❌ Menu: nao achei o item Dispenser no base.html.")

if 'id="link-sistema"' in b:
    res.append("⏭️  Menu: item Status do Sistema ja existia.")
else:
    m = re.search(r'<a href="/controle"[\s\S]*?</a>\s*\{% endif %\}', b)
    if m:
        b = b[:m.end()] + LINK_SIS + b[m.end():]; res.append("✅ Menu: item Status do Sistema adicionado (so Adm/Dono).")
    else: res.append("❌ Menu: nao achei o item Painel de Controle no base.html.")

if "link-separador';" in b:
    res.append("⏭️  Menu: destaque do item atual ja estava aplicado.")
else:
    a = "else if (caminho === '/dispenser') idAlvo = 'link-dispenser';"
    if b.count(a) == 1:
        b = b.replace(a, a + "\n                else if (caminho === '/separador') idAlvo = 'link-separador';\n                else if (caminho === '/sistema') idAlvo = 'link-sistema';", 1)
        res.append("✅ Menu: destaque do item atual aplicado.")
    else: res.append("❌ Menu: nao achei o trecho do destaque do item atual.")
open(caminho_base, "w", encoding="utf-8").write(b)

print("\n".join(res))
print()
ok = subprocess.run(["node", "-c", SERVER], capture_output=True, text=True)
if ok.returncode == 0: print("✅ server.js sem erro de sintaxe.")
else:
    print("❌ ERRO DE SINTAXE no server.js:"); print(ok.stderr)
    print("Para voltar:  cp " + SERVER + ".bak_" + carimbo + " " + SERVER); sys.exit(1)
if any(l.startswith("❌") for l in res): print("⚠️  Teve ❌ acima. Me mande essas linhas antes de reiniciar o site.")
else:
    print("\nTudo certo! Agora reinicie o site:\n    sudo systemctl restart site_esteira\nDepois aperte Ctrl+Shift+R no navegador.")
